  // ======================================================
  // FETCH ALL INVOICE HEADERS
  // LATEST BILL FIRST
  // ======================================================

  
const fetchInvoiceHeader = async (
  selectedFromDate = filterFromDate,
  selectedToDate = filterToDate
) => {
  const requestOptions = {
    method: "GET",
    redirect: "follow",
  };

  const DATE_BATCH_SIZE = 5;
  const DETAIL_BATCH_SIZE = 8;

  try {
    // 1. FORMAT DATE
    const formatDateForAPI = (date) => {
      if (!date) return "";

      if (date instanceof Date) {
        if (Number.isNaN(date.getTime())) return "";

        const year = date.getFullYear();
        const month = String(date.getMonth() + 1).padStart(2, "0");
        const day = String(date.getDate()).padStart(2, "0");

        return `${year}-${month}-${day}`;
      }

      const value = String(date).trim();

      if (/^\d{4}-\d{2}-\d{2}$/.test(value)) {
        return value;
      }

      const parsedDate = new Date(value);

      if (Number.isNaN(parsedDate.getTime())) return "";

      const year = parsedDate.getFullYear();
      const month = String(parsedDate.getMonth() + 1).padStart(2, "0");
      const day = String(parsedDate.getDate()).padStart(2, "0");

      return `${year}-${month}-${day}`;
    };

    const formattedFromDate = formatDateForAPI(selectedFromDate);
    const formattedToDate = formatDateForAPI(selectedToDate);

    console.log("CATERERS FROM DATE:", formattedFromDate);
    console.log("CATERERS TO DATE:", formattedToDate);

    // 2. VALIDATE DATE RANGE
    if (!formattedFromDate || !formattedToDate) {
      setInvoiceheaders([]);
      setPageNo(1);
      setTotalPages(1);
      return;
    }

    if (formattedFromDate > formattedToDate) {
      toast.error("From Date cannot be greater than To Date.");

      setInvoiceheaders([]);
      setPageNo(1);
      setTotalPages(1);
      return;
    }

    // 3. CREATE DATE LIST
    const getDateList = (startDate, endDate) => {
      const dates = [];
      const current = new Date(`${startDate}T00:00:00`);
      const end = new Date(`${endDate}T00:00:00`);

      if (
        Number.isNaN(current.getTime()) ||
        Number.isNaN(end.getTime())
      ) {
        return dates;
      }

      while (current <= end) {
        const year = current.getFullYear();
        const month = String(current.getMonth() + 1).padStart(2, "0");
        const day = String(current.getDate()).padStart(2, "0");

        dates.push(`${year}-${month}-${day}`);

        current.setDate(current.getDate() + 1);
      }

      return dates;
    };

    const selectedDates = getDateList(
      formattedFromDate,
      formattedToDate
    );

    if (selectedDates.length === 0) {
      setInvoiceheaders([]);
      setPageNo(1);
      setTotalPages(1);
      return;
    }

    console.log("SELECTED DATES:", selectedDates);

    // 4. NORMALIZE API RESPONSE
    const getRowsFromResponse = (result) => {
      if (Array.isArray(result)) return result;
      if (Array.isArray(result?.data)) return result.data;
      if (Array.isArray(result?.Data)) return result.Data;

      return [];
    };

    const getTotalPages = (result) => {
      const value = Number(
        result?.total_pages ??
          result?.TotalPages ??
          result?.totalPages ??
          result?.pages ??
          1
      );

      return Number.isFinite(value) && value >= 1
        ? Math.floor(value)
        : 1;
    };

    // 5. FETCH ALL PAGES FOR ONE DATE
    const fetchInvoicesForDate = async (selectedDate) => {
      const buildInvoiceUrl = (page) =>
        `https://amrutdairyapi.microtechsolutions.net.in/php/get/gettblpage.php` +
        `?Table=invoiceheader` +
        `&PageNo=${page}` +
        `&InvoiceDate=${encodeURIComponent(selectedDate)}`;

      const firstResponse = await fetch(
        buildInvoiceUrl(1),
        requestOptions
      );

      if (!firstResponse.ok) {
        throw new Error(
          `Invoice API failed for ${selectedDate}, page 1`
        );
      }

      const firstResult = await firstResponse.json();

      const dateInvoices = [
        ...getRowsFromResponse(firstResult),
      ];

      const totalPagesForDate = getTotalPages(firstResult);

      // Fetch remaining pages in parallel
      if (totalPagesForDate > 1) {
        const remainingPages = Array.from(
          { length: totalPagesForDate - 1 },
          (_, index) => index + 2
        );

        const remainingResults = await Promise.all(
          remainingPages.map(async (page) => {
            const response = await fetch(
              buildInvoiceUrl(page),
              requestOptions
            );

            if (!response.ok) {
              throw new Error(
                `Invoice API failed for ${selectedDate}, page ${page}`
              );
            }

            const result = await response.json();

            return getRowsFromResponse(result);
          })
        );

        remainingResults.forEach((rows) => {
          dateInvoices.push(...rows);
        });
      }

      console.log(
        `Invoices fetched for ${selectedDate}:`,
        dateInvoices.length
      );

      return dateInvoices;
    };

    // 6. FETCH DATES IN BATCHES
    const allInvoiceData = [];

    for (
      let start = 0;
      start < selectedDates.length;
      start += DATE_BATCH_SIZE
    ) {
      const dateBatch = selectedDates.slice(
        start,
        start + DATE_BATCH_SIZE
      );

      const batchResults = await Promise.all(
        dateBatch.map((date) => fetchInvoicesForDate(date))
      );

      batchResults.forEach((rows) => {
        allInvoiceData.push(...rows);
      });
    }

    // 7. REMOVE DUPLICATE INVOICES
    const uniqueInvoices = Array.from(
      new Map(
        allInvoiceData.map((invoice, index) => [
          invoice?.Id != null
            ? String(invoice.Id)
            : `${invoice?.InvoiceNo ?? "invoice"}-${invoice?.InvoiceDate ?? ""}-${index}`,
          invoice,
        ])
      ).values()
    );

    // Latest invoice first
    uniqueInvoices.sort(
      (a, b) => Number(b?.Id || 0) - Number(a?.Id || 0)
    );

    console.log("TOTAL RAW INVOICES:", uniqueInvoices.length);

    if (uniqueInvoices.length === 0) {
      setInvoiceheaders([]);
      setPageNo(1);
      setTotalPages(1);
      return;
    }

    // 8. ACCOUNT AND ADDRESS CACHE
    const accountCache = new Map();
    const addressCache = new Map();

    const normalizeSingleRecord = (result) => {
      if (Array.isArray(result)) return result[0] || null;
      if (Array.isArray(result?.data)) return result.data[0] || null;
      if (Array.isArray(result?.Data)) return result.Data[0] || null;

      return result?.data || result?.Data || result || null;
    };

    const getAccountDetails = async (accountId) => {
      const key = String(accountId);

      if (!accountCache.has(key)) {
        const request = (async () => {
          try {
            const response = await fetch(
              `https://amrutdairyapi.microtechsolutions.net.in/php/getbyid.php?Table=Account&Colname=Id&Colvalue=${encodeURIComponent(key)}`,
              requestOptions
            );

            if (!response.ok) {
              console.error(
                "Account API failed:",
                key,
                response.status
              );

              return null;
            }

            return normalizeSingleRecord(
              await response.json()
            );
          } catch (error) {
            console.error("Account API error:", key, error);
            return null;
          }
        })();

        accountCache.set(key, request);
      }

      return accountCache.get(key);
    };

    const getAddressDetails = async (accountId) => {
      const key = String(accountId);

      if (!addressCache.has(key)) {
        const request = (async () => {
          try {
            const response = await fetch(
              `https://amrutdairyapi.microtechsolutions.net.in/php/getbyid.php?Table=Address&Colname=AccountId&Colvalue=${encodeURIComponent(key)}`,
              requestOptions
            );

            if (!response.ok) {
              console.error(
                "Address API failed:",
                key,
                response.status
              );

              return null;
            }

            return normalizeSingleRecord(
              await response.json()
            );
          } catch (error) {
            console.error("Address API error:", key, error);
            return null;
          }
        })();

        addressCache.set(key, request);
      }

      return addressCache.get(key);
    };

    // 9. PROCESS INVOICES WITH LIMITED CONCURRENCY
    const invoicesList = new Array(uniqueInvoices.length);

    const processInvoice = async (invoice, index) => {
      const accountId = invoice?.AccountId;

      let accountDetails = null;
      let addressDetails = null;

      if (
        accountId !== null &&
        accountId !== undefined &&
        String(accountId).trim() !== "" &&
        Number(accountId) !== 0
      ) {
        [accountDetails, addressDetails] = await Promise.all([
          getAccountDetails(accountId),
          getAddressDetails(accountId),
        ]);
      }

      const customerType = String(
        addressDetails?.CustomerType ??
          addressDetails?.customerType ??
          accountDetails?.CustomerType ??
          accountDetails?.customerType ??
          invoice?.CustomerType ??
          invoice?.customerType ??
          ""
      )
        .trim()
        .toUpperCase();

      invoicesList[index] = {
        ...invoice,

        accountDetails: {
          ...(accountDetails || {}),

          AccountName:
            accountDetails?.AccountName ??
            invoice?.AccountName ??
            "",

          CustomerType: customerType,
        },

        addressDetails,

        CustomerType: customerType,
      };
    };

    for (
      let start = 0;
      start < uniqueInvoices.length;
      start += DETAIL_BATCH_SIZE
    ) {
      const invoiceBatch = uniqueInvoices.slice(
        start,
        start + DETAIL_BATCH_SIZE
      );

      await Promise.all(
        invoiceBatch.map((invoice, batchIndex) =>
          processInvoice(invoice, start + batchIndex)
        )
      );
    }

    console.log("TOTAL INVOICES WITH DETAILS:", invoicesList.length);
    console.log("UNIQUE ACCOUNT REQUESTS:", accountCache.size);
    console.log("UNIQUE ADDRESS REQUESTS:", addressCache.size);

    // 10. FILTER CATERERS ONLY
    const catererInvoices = invoicesList.filter((invoice) => {
      const customerType = String(
        invoice?.addressDetails?.CustomerType ??
          invoice?.addressDetails?.customerType ??
          invoice?.accountDetails?.CustomerType ??
          invoice?.accountDetails?.customerType ??
          invoice?.CustomerType ??
          invoice?.customerType ??
          ""
      )
        .trim()
        .toUpperCase();

      return customerType === PAGE_CUSTOMER_TYPE;
    });

    console.log("ALL INVOICES:", invoicesList.length);
    console.log("CATERERS INVOICES:", catererInvoices.length);

    // 11. UPDATE UI
    setInvoiceheaders(catererInvoices);
    setPageNo(1);
    setTotalPages(1);

    // Check history without blocking invoice display
    void checkInvoiceHistory(catererInvoices);
  } catch (error) {
    console.error(
      "Error fetching Caterers invoice headers:",
      error
    );

    toast.error(
      "Unable to load Caterers invoices. Please try again."
    );

    setInvoiceheaders([]);
    setPageNo(1);
    setTotalPages(1);
  }
};




