  // =====================================================
  // CHECK INVOICE EDIT HISTORY
  // =====================================================
  
const checkInvoiceHistory = async (invoiceList) => {
  try {
    const historyStatus = {};

    // Only invoices with a valid Id
    const validInvoices = invoiceList.filter(
      (invoice) => invoice?.Id !== null &&
                   invoice?.Id !== undefined &&
                   invoice?.Id !== ""
    );

    // Maximum 10 API requests at a time
    const batchSize = 10;

    for (
      let start = 0;
      start < validInvoices.length;
      start += batchSize
    ) {
      const batch = validInvoices.slice(
        start,
        start + batchSize
      );

      await Promise.all(
        batch.map(async (invoice) => {
          const invoiceId = invoice.Id;

          try {
            const response = await axios.get(
              `https://amrutdairyapi.microtechsolutions.net.in/php/getbyid.php?Table=invoiceheader_history&Colname=InvoiceId&Colvalue=${encodeURIComponent(invoiceId)}`
            );

            const data = response.data;

            const historyList = Array.isArray(data)
              ? data
              : Array.isArray(data?.data)
                ? data.data
                : data?.data
                  ? [data.data]
                  : data
                    ? [data]
                    : [];

            const hasHistory = historyList.length > 0;

            historyStatus[String(invoiceId)] = hasHistory;

            console.log("HISTORY CHECK:", {
              InvoiceId: invoiceId,
              HistoryCount: historyList.length,
              HasHistory: hasHistory,
            });
          } catch (error) {
            console.error(
              `History check failed for InvoiceId ${invoiceId}:`,
              error
            );

            historyStatus[String(invoiceId)] = false;
          }
        })
      );
    }

    console.log(
      "========== FINAL INVOICE HISTORY STATUS =========="
    );

    console.log(historyStatus);

    setInvoiceHistoryStatus(historyStatus);
  } catch (error) {
    console.error("History status error:", error);
  }
};


