// ======================================================
// MINIMIZE CURRENT CATERERS BILL
// ======================================================

const handleMinimizeBill = () => {
  try {
    console.log("========== MINIMIZE CATERERS BILL START ==========");

    console.log("Current product rows:", rows);
    console.log("Selected product ID:", selectedProductID);
    console.log("Selected product name:", selectedProductName);
    console.log("Product name:", productName);
    console.log("Quantity:", quantity);
    console.log("Rate:", rate);
    console.log("Amount:", amount);

    const draftId =
      isEditing && editId
        ? `edit-${editId}`
        : `new-${Date.now()}-${Math.random()
            .toString(36)
            .slice(2, 9)}`;

    // Preserve an independent copy of saved product rows.
    const savedRows = JSON.parse(
      JSON.stringify(Array.isArray(rows) ? rows : [])
    );

    const draftBill = {
      draftId,

      // Edit information
      isEditing,
      editId: editId || null,

      // Invoice information
      invoiceNo,
      invoiceDate,
      invoiceTime,
      device,

      // Customer information
      customerName,
      selectedCustomerName,
      selectedCustomerAddress,
      selectedAccount,
      phone,
      acctGSTNo,

      // Saved product rows
      rows: savedRows,

      // Current product input
      selectedProductID,
      selectedProductName,
      productName,
      quantity,
      rate,
      amount,

      // Payment information
      paymentMode,
      cashAmount,
      onlineAmount,
      receivedAmount,

      // Amount details
      discount,
      transport,

      // GST details
      isGST,
      cgst,
      cgstAmount,
      sgst,
      sgstAmount,
      igst,
      igstAmount,

      // Other details
      billFor,
      machineID,

      // Current editing row
      editingRow,

      minimizedAt: new Date().toISOString(),
    };

    console.log("Draft ID:", draftBill.draftId);
    console.log("Draft product rows:", draftBill.rows);
    console.log("Draft current product:", {
      selectedProductID: draftBill.selectedProductID,
      productName: draftBill.productName,
      selectedProductName: draftBill.selectedProductName,
      quantity: draftBill.quantity,
      rate: draftBill.rate,
      amount: draftBill.amount,
    });
    console.log("Complete draft:", draftBill);

    setMinimizedBills((prev) => {
      const existingIndex = prev.findIndex(
        (bill) => bill.draftId === draftId
      );

      if (existingIndex !== -1) {
        const updatedBills = [...prev];
        updatedBills[existingIndex] = draftBill;
        return updatedBills;
      }

      return [...prev, draftBill];
    });

    // Close without resetting the form.
    setIsDrawerOpen(false);
    setShowDropdown(false);
    setProductDropdownOpen(false);

    console.log("========== MINIMIZE CATERERS BILL END ==========");

    toast.success("Caterers bill minimized successfully.");
  } catch (error) {
    console.error("Error minimizing Caterers bill:", error);
    toast.error("Unable to minimize Caterers bill.");
  }
};




// ======================================================
// RESUME MINIMIZED CATERERS BILL
// ======================================================

const handleResumeBill = (billId) => {
  try {
    // Find the selected minimized bill.
    const bill = minimizedBills.find(
      (item) => String(item.draftId) === String(billId)
    );

    if (!bill) {
      toast.error("Minimized Caterers bill not found.");
      return;
    }

    console.log("========== RESUME CATERERS BILL ==========");
    console.log("Draft ID:", bill.draftId);
    console.log("Draft bill:", bill);
    console.log("Saved product rows:", bill.rows);

    // ==================================================
    // INVOICE DETAILS
    // ==================================================
    setInvoiceNo(bill.invoiceNo || "");

    setInvoiceDate(
      bill.invoiceDate || new Date()
    );

    setInvoiceTime(
      bill.invoiceTime || new Date()
    );

    setDevice(bill.device || "");

    // ==================================================
    // CUSTOMER DETAILS
    // ==================================================
    setSelectedAccount(
      bill.selectedAccount || ""
    );

    setCustomerName(
      bill.customerName || ""
    );

    setSelectedCustomerName(
      bill.selectedCustomerName || ""
    );

    setSelectedCustomerAddress(
      bill.selectedCustomerAddress || ""
    );

    setPhone(
      bill.phone || ""
    );

    setacctGSTNo(
      bill.acctGSTNo || ""
    );

    // ==================================================
    // PRODUCT ROWS
    // ==================================================
    const restoredRows = JSON.parse(
      JSON.stringify(
        Array.isArray(bill.rows) ? bill.rows : []
      )
    );

    setRows(restoredRows);

    console.log("Restored product rows:", restoredRows);

    // ==================================================
    // CURRENT PRODUCT INPUT
    // ==================================================
    setSelectedProductId(
      bill.selectedProductID || ""
    );

    setSelectedProductName(
      bill.selectedProductName || ""
    );

    setProductName(
      bill.productName || ""
    );

    setQuantity(
      bill.quantity ?? ""
    );

    setRate(
      bill.rate ?? ""
    );

    SetAmount(
      bill.amount ?? ""
    );

    // ==================================================
    // PAYMENT DETAILS
    // ==================================================
    setPaymentMode(
      bill.paymentMode || ""
    );

    setCashAmount(
      bill.cashAmount ?? ""
    );

    setOnlineAmount(
      bill.onlineAmount ?? ""
    );

    setReceivedAmount(
      bill.receivedAmount ?? ""
    );

    // ==================================================
    // DISCOUNT AND TRANSPORT
    // ==================================================
    setDiscount(
      bill.discount ?? ""
    );

    setTransport(
      bill.transport ?? ""
    );

    // ==================================================
    // GST DETAILS
    // ==================================================
    setIsGST(
      bill.isGST ?? false
    );

    setCGST(
      bill.cgst ?? ""
    );

    setCGSTAmount(
      bill.cgstAmount ?? ""
    );

    setSGST(
      bill.sgst ?? ""
    );

    setSGSTAmount(
      bill.sgstAmount ?? ""
    );

    setIGST(
      bill.igst ?? ""
    );

    setIGSTAmount(
      bill.igstAmount ?? ""
    );

    // ==================================================
    // OTHER DETAILS
    // ==================================================
    setBillFor(
      bill.billFor || ""
    );

    setMachineID(
      bill.machineID || ""
    );

    // ==================================================
    // EDIT INFORMATION
    // ==================================================
    setIsEditing(
      bill.isEditing ?? false
    );

    setEditId(
      bill.editId || null
    );

    // ==================================================
    // CURRENT EDITING ROW
    // ==================================================
    setEditingRow(
      bill.editingRow ?? null
    );

    // ==================================================
    // OPEN DRAWER
    // ==================================================
    setIsDrawerOpen(true);
    setShowDropdown(false);

    // ==================================================
    // REMOVE ONLY THE RESUMED BILL
    // ==================================================
    setMinimizedBills((prev) =>
      prev.filter(
        (item) =>
          String(item.draftId) !== String(bill.draftId)
      )
    );

    console.log("Caterers bill resumed successfully.");
    console.log("========================================");

    toast.success(
      "Minimized Caterers bill resumed successfully."
    );
  } catch (error) {
    console.error(
      "Error resuming Caterers bill:",
      error
    );

    toast.error(
      "Unable to resume Caterers bill."
    );
  }
};




// ======================================================
// REMOVE MINIMIZED CATERERS BILL
// ======================================================
const handleRemoveMinimizedBill = (billId) => {
  try {
    setMinimizedBills((prev) => {
      const updatedBills = prev.filter(
        (item) => item.draftId !== billId
      );

      localStorage.setItem(
        "minimizedCaterersBills",
        JSON.stringify(updatedBills)
      );

      return updatedBills;
    });

    toast.success("Minimized Caterers bill removed.");
  } catch (error) {
    console.error("Error removing minimized Caterers bill:", error);
    toast.error("Unable to remove minimized Caterers bill.");
  }
};

