// ======================================================
// EDIT SAVED INVOICE
// ======================================================

const handleEdit = async (row) => {
  try {
    // ==================================================
    // 0. GET LOGGED-IN USER ROLE
    // ==================================================
    const userRole = String(
      sessionStorage.getItem("UserRole") || "",
    )
      .trim()
      .toUpperCase();

    console.log("EDIT USER ROLE:", userRole);

    // ==================================================
    // 1. GET ORIGINAL ROW
    // ==================================================
    const originalData = row?.original;

    if (!originalData) {
      toast.error("Invoice data not found.");
      return;
    }

    const rowId = originalData.Id;

    if (!rowId) {
      toast.error("Invoice ID not found.");
      return;
    }

    // ==================================================
    // 2. GET INVOICE HEADER
    // ==================================================
    const invheader =
      invoiceheaders.find(
        (h) => String(h.Id) === String(rowId),
      ) || originalData;

    if (!invheader) {
      toast.error("Invoice header not found.");
      return;
    }

    // ==================================================
    // 3. EDIT DATE RESTRICTION
    //
    // ADMIN
    // -> Can edit any date
    //
    // SALE
    // -> Only today's entry
    //
    // SALE2
    // -> Only today's entry
    // ==================================================
    if (
      userRole === "SALE" ||
      userRole === "SALE2"
    ) {
      const rawInvoiceDate =
        invheader?.InvoiceDate?.date ||
        invheader?.InvoiceDate ||
        originalData?.InvoiceDate?.date ||
        originalData?.InvoiceDate ||
        "";

      if (!rawInvoiceDate) {
        toast.error("Invoice date not found.");
        return;
      }

      const invoiceMoment = moment(rawInvoiceDate);
      const todayMoment = moment();

      console.log(
        "EDIT INVOICE DATE:",
        invoiceMoment.format("DD-MM-YYYY"),
      );

      console.log(
        "TODAY DATE:",
        todayMoment.format("DD-MM-YYYY"),
      );

      if (!invoiceMoment.isValid()) {
        toast.error("Invalid invoice date.");
        return;
      }

      // SALE / SALE2 -> TODAY ONLY
      if (
        !invoiceMoment.isSame(
          todayMoment,
          "day",
        )
      ) {
        toast.error(
          "Only today's Sales Entry can be edited.",
        );
        return;
      }
    }

    // ==================================================
    // 4. GET SAVED INVOICE DETAILS
    // ==================================================
    const detailResponse = await axios.get(
      `https://amrutdairyapi.microtechsolutions.net.in/php/getbyid.php?Table=invoicedetail&Colname=InvoiceId&Colvalue=${rowId}`,
    );

    let invdetail = [];

    if (Array.isArray(detailResponse.data)) {
      invdetail = detailResponse.data;
    } else if (
      Array.isArray(detailResponse.data?.data)
    ) {
      invdetail = detailResponse.data.data;
    } else if (detailResponse.data) {
      invdetail = [detailResponse.data];
    }

    console.log(
      "EDIT INVOICE DETAILS:",
      invdetail,
    );

    // ==================================================
    // 5. MAP SAVED PRODUCTS
    // ==================================================
    const mappedRows = invdetail.map((detail) => {
      const matchedProduct =
        productOptions.find(
          (item) =>
            String(item.value) ===
            String(detail.ProductId),
        );

      return {
        Id: detail.Id,
        InvoiceId: detail.InvoiceId,
        ProductId: detail.ProductId,

        ProductName:
          matchedProduct?.label ||
          detail.ProductName ||
          "",

        Quantity:
          parseFloat(detail.Quantity) || 0,

        Rate:
          parseFloat(detail.Rate) || 0,

        Amount:
          parseFloat(detail.Amount) || 0,

        CGSTPercentage:
          parseFloat(detail.CGSTPercentage) || 0,

        CGSTAmount:
          parseFloat(detail.CGSTAmount) || 0,

        SGSTPercentage:
          parseFloat(detail.SGSTPercentage) || 0,

        SGSTAmount:
          parseFloat(detail.SGSTAmount) || 0,

        IGSTPercentage:
          parseFloat(detail.IGSTPercentage) || 0,

        IGSTAmount:
          parseFloat(detail.IGSTAmount) || 0,

        DiscountAmt:
          parseFloat(detail.DiscountAmt) || 0,
      };
    });

    console.log(
      "EDIT MAPPED ROWS:",
      mappedRows,
    );

    // ==================================================
    // 6. CUSTOMER
    // ==================================================
    fetchAccounts(invheader.AccountId);

    fetchAccountName(invheader.AccountId);

    fetchPreviousBalance(
      invheader.AccountId,
      rowId,
    );

    setSelectedAccount(
      invheader.AccountId,
    );

    // ==================================================
    // 7. DATE CONVERSION
    // ==================================================
    const convertDateForInput = (dateValue) => {
      if (!dateValue) {
        return "";
      }

      const dateStr =
        typeof dateValue === "string"
          ? dateValue
          : dateValue?.date;

      if (!dateStr) {
        return "";
      }

      const datePart = String(dateStr)
        .split(" ")[0]
        .split("T")[0];

      const parts = datePart.split("-");

      if (parts.length === 3) {
        const [
          year,
          month,
          day,
        ] = parts;

        return `${year}-${month}-${day}`;
      }

      return "";
    };

    const invoiceDate =
      convertDateForInput(
        invheader.InvoiceDate,
      );

    // ==================================================
    // 8. HEADER DATA
    // ==================================================
    setInvoiceNo(
      invheader.InvoiceNo != null
        ? String(invheader.InvoiceNo)
        : "",
    );

    setInvoiceDate(invoiceDate);

    setPhone(
      invheader.ContactNo || "",
    );

    setDevice(
      getDeviceForLoggedInUser(),
    );

    setBillFor(
      invheader.BillFor || "",
    );

    setMachineID(
      invheader.MachineID
        ? String(invheader.MachineID)
        : "",
    );

    setIsGST(
      Number(invheader.IsGST) === 1,
    );

    // ==================================================
    // 9. IMPORTANT - EDIT TIME
    //
    // DO NOT TAKE TIME FROM DATABASE
    //
    // Whenever Edit is clicked,
    // take CURRENT SYSTEM TIME.
    // ==================================================
    const currentSystemTime = new Date();

    setInvoiceTime(
      currentSystemTime,
    );

    console.log(
      "EDIT CURRENT SYSTEM TIME:",
      moment(currentSystemTime).format(
        "hh:mm A",
      ),
    );

    // ==================================================
    // 10. PAYMENT DATA
    // ==================================================
    setPaymentMode(
      invheader.PaymentMode || "",
    );

    setCashAmount(
      invheader.CashAmount != null
        ? String(invheader.CashAmount)
        : "",
    );

    setOnlineAmount(
      invheader.OnlineAmount != null
        ? String(invheader.OnlineAmount)
        : "",
    );

    setDiscount(
      invheader.Discount != null
        ? String(invheader.Discount)
        : "",
    );

    setReceivedAmount(
      invheader.ReceivedAmount != null
        ? String(
            invheader.ReceivedAmount,
          )
        : "",
    );

    setTransport(
      invheader.Transport != null
        ? String(invheader.Transport)
        : "",
    );

    // ==================================================
    // 11. LOAD SAVED ROWS
    // ==================================================
    setRows(mappedRows);

    // ==================================================
    // 12. LOAD FIRST PRODUCT
    // ==================================================
    if (mappedRows.length > 0) {
      const firstRow = mappedRows[0];

      setSelectedProductId(
        firstRow.ProductId
          ? String(firstRow.ProductId)
          : "",
      );

      setSelectedProductName(
        firstRow.ProductName || "",
      );

      setProductName(
        firstRow.ProductName || "",
      );

      setQuantity(
        firstRow.Quantity != null
          ? String(firstRow.Quantity)
          : "",
      );

      setRate(
        firstRow.Rate != null
          ? String(firstRow.Rate)
          : "",
      );

      SetAmount(
        firstRow.Amount != null
          ? String(firstRow.Amount)
          : "",
      );

      setDiscount(
        firstRow.DiscountAmt != null
          ? String(
              firstRow.DiscountAmt,
            )
          : "",
      );

      setCGST(
        firstRow.CGSTPercentage || 0,
      );

      setCGSTAmount(
        firstRow.CGSTAmount || 0,
      );

      setSGST(
        firstRow.SGSTPercentage || 0,
      );

      setSGSTAmount(
        firstRow.SGSTAmount || 0,
      );

      setIGST(
        firstRow.IGSTPercentage || 0,
      );

      setIGSTAmount(
        firstRow.IGSTAmount || 0,
      );
    } else {
      setSelectedProductId("");
      setSelectedProductName("");
      setProductName("");
      setQuantity("");
      setRate("");
      SetAmount("");
    }

    // ==================================================
    // 13. EDIT MODE
    // ==================================================
    setEditId(rowId);

    setIsEditing(true);

    setIsDrawerOpen(true);

    // ==================================================
    // DEBUG
    // ==================================================
    console.log(
      "======================================",
    );

    console.log(
      "EDIT ID:",
      rowId,
    );

    console.log(
      "EDIT USER ROLE:",
      userRole,
    );

    console.log(
      "EDIT HEADER:",
      invheader,
    );

    console.log(
      "EDIT ROWS:",
      mappedRows,
    );

    console.log(
      "EDIT TIME:",
      moment(currentSystemTime).format(
        "hh:mm A",
      ),
    );

    console.log(
      "======================================",
    );
  } catch (error) {
    console.error(
      "EDIT INVOICE ERROR:",
      error,
    );

    toast.error(
      "Unable to load saved invoice.",
    );
  }
};

