                                Number(updatedRows[index].Rate) || 0;

                              updatedRows[index] = {
                                ...updatedRows[index],
                                Quantity: qty,
                                Amount: (Number(qty) || 0) * currentRate,
                              };

                              setRows(updatedRows);
